mapper.select:
  SELECT COUNT(*)
  FROM posts
  WHERE round_id = #{roundId}
    AND user_id = #{userId}
    AND post_status != 'NONE'
AND DATE(posted_at) = CURRENT_DATE

SELECT u.user_id, u.nickname, u.profile_image_url
FROM post_reactions pr
JOIN users u ON pr.user_id = u.user_id
WHERE pr.post_id = #{postId}
AND pr.reaction_type = #{reactionType}
ORDER BY pr.created_at DESC

SELECT COUNT(*) > 0
FROM rounds r
WHERE r.round_id = #{roundId}
  AND r.round_status = 'ONGOING'
  AND EXISTS (
    SELECT 1
    FROM round_history rh
    WHERE rh.round_id = r.round_id
      AND rh.user_id = #{userId}
)
  AND (
        EXISTS (
            SELECT 1
            FROM `groups` g
            WHERE g.group_id = r.group_id
              AND g.user_id = #{userId}
        )
        OR EXISTS (
        SELECT 1
        FROM group_users gu
        WHERE gu.group_id = r.group_id
          AND gu.user_id = #{userId}
          AND gu.group_user_status = 'ACTIVE'
    )
    )

SELECT COUNT(*)
FROM post_approvals
WHERE post_id = #{postId} AND user_id = #{userId}

mapper.update:
UPDATE posts
SET approve_count = approve_count + 1
WHERE post_id = #{postId}

UPDATE posts
SET reject_count = reject_count + 1
WHERE post_id = #{postId}

mapper.select:
SELECT nickname
FROM users
WHERE user_id = #{userId}
